Š. Bộ trưởng Bộ Tài chính quy định các nội dung sau: tiêu chí đánh giá,
phân loại mức độ rủi ro và việc áp dụng quản lý rủi ro trong hoạt động nghiệp vụ
quản lý thuế.$md$,$md$Luật quản lý thuế 2025_Điều33$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều34$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 34. Quản lý tuân thủ trong quản lý thuế$md$,$md$Quản lý tuân thủ trong quản lý thuế$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều34_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Cơ quan thuế thực hiện quản lý tuân thủ đê phân bổ nguồn lực hiệu quả,
khuyến khích sự tuân thủ tự nguyện và tạo môi trường kinh doanh công bằng,
bao gồm:
thuế của người nộp thuế, đồng thời duy trì hồ sơ điện tử cho từng người nộp thuế,
gồm các thông tin về: tần suất vi phạm pháp luật về thuế; tính chất và mức độ của
hành vi vi phạm; mức độ hợp tác với cơ quan quản lý thuế trong việc thực hiện
thủ tục thuế, kiểm tra và chấp hành các quyết định xử lý vi phạm và các thông tin
khác liên quan đến nghĩa vụ thuế;
<!-- Page Break -->
## Page 39
39
tự nguyện với các biện pháp kiểm tra, giám sát dựa trên kết quả đánh giá mức độ
tuân thủ, mức độ rủi ro và hành vỉ tuân thủ của người nộp thuế;
thuế, sẵn sàng kết nối, chia sẻ dữ liệu điện tử với cơ quan quản lý thuế, bao gồm
dữ liệu về số kế toán, hóa đơn, chứng từ và các tài liệu liên quan đến nghĩa vụ
thuế thông qua Hệ thống thông tin quản lý thuế theo quy định của Chính phủ.
Chính phủ quy định chỉ tiết về điều kiện, phạm vi và hình thức áp dụng chế
độ ưu tiên đối với người nộp thuế tuân thủ pháp luật.$md$,$md$Luật quản lý thuế 2025_Điều34$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
