insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều35_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Hệ thống thông tin quản lý thuế xử lý tập trung, tích hợp; cung cấp các
dịch vụ công trực tuyến toàn trình, dịch vụ số cho người nộp thuế; bảo đảm thu
