insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều35_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Cơ sở dữ liệu quản lý thuế được xây dựng, phát triển và vận hành trên
nền tảng dữ liệu só, kết nối và đồng bộ với hệ thống cơ sở dữ liệu quốc gia, cơ sở
dữ liệu của các Bộ, ngành, các tổ chức hợp tác quốc tế và tổ chức có liên quan.
Cơ quan quản lý thuế được quyền thu thập, tiếp cận, sử dụng và mua sắm các cơ
