insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều37_K1_Dr$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm r$md$,$md$Khi cơ quan quản lý thuế kiểm tra thuế, người nộp thuế có quyền từ chối$md$,$md$Luật quản lý thuế 2025_Điều37_K1$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều37_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Người nộp thuế có nghĩa vụ sau:
nhiệm trước pháp luật về tính chính xác, trung thực, đầy đủ của hồ sơ thuế và các
tài liệu cung cấp cho cơ quan quản lý thuế trong quá trình giải quyết hồ sơ thuế;
phạt. Trường hợp số tiền phải nộp đã được cơ quan quản lý thuế cung cấp mã định
danh khoản phải nộp thì người nộp thuê nộp theo mã định danh khoản phải nộp;
quy định;
sinh nghĩa vụ thuế, khấu trừ thuế và giao dịch phải kê khai thông tỉn về thuế;
loại, giá trị thực thanh toán khi bán hàng hóa, cung cấp dịch vụ theo quy định của
pháp luật;
xác định nghĩa vụ thuế dưới dạng văn bản giấy hoặc điện tử; cung cấp thông tỉn
cho cơ quan quản lý thuế để thực hiện trao đổi thông tin với cơ quan quản lý thuế
nước ngoài theo điều ước quốc tế, thỏa thuận quốc tế về thuế mà nước Cộng hòa
xã hội chủ nghĩa Việt Nam là thành viên hoặc là bên ký kết; giải thích việc tính
thuế, khoản thu khác, khai thuế, khoản thu khác, nộp thuế, khoản thu khác theo
yêu cầu của cơ quan quản lý thuế;
công chức quản lý thuế theo quy định của pháp luật;
<!-- Page Break -->
## Page 43
4
1) Chịu trách nhiệm thực hiện nghĩa vụ thuế, khoản thu khác theo quy định
của pháp luật bao gồm cả trong trường hợp người đại diện theo pháp luật hoặc đại
diện theo ủy quyền thay mặt người nộp thuế thực hiện thủ tục về thuế, khoản thu
khác sai quy định;
tin nghĩa vụ thuế với cơ quan quản lý thuế;
I) Sử dụng đúng mục đích các hàng hóa, dịch vụ miễn thuế, khoản thu khác,
không chịu thuế theo kê khai; nếu thay đổi mục đích, phải kê khai lại và nộp tiên
thuế, khoản thu khác và các khoản phát sinh theo quy định của pháp luật;
hỗ sơ về giao dịch liên kết và các bên liên kết của người nộp thuế, kể cả bên liên
kết ở nước ngoài;
trung thực và đầy đủ các khoản thu từ hoạt động hợp tác, tài trợ và hợp đồng kinh
tế với tổ chức, cá nhân nước ngoài sử dụng cho mục đích xã hội, môi trường theo
quy định của pháp luật về thuế và pháp luật có liên quan;
định xử lý về thuế, khoản thu khác của cơ quan quản lý thuế. Trường hợp không
đồng ý với số tiền thuế, khoản thu khác do cơ quan quản lý thuế ấn định thì người
nộp thuế vẫn phải nộp số tiền thuế, khoản thu khác đó, đồng thời có quyền đề nghị
cơ quan quản lý thuế giải thích hoặc khiếu nại, khởi kiện về việc ấn định thuế.
Người nộp thuế có trách nhiệm cung cấp các hồ sơ, tài liệu để chứng minh cho
việc khiếu nại, khởi kiện;
chấp hành quyết định kiểm tra thuế tại trụ sở người nộp thuế của cơ quan quản
lý thuế; chấp hành thông báo yêu cầu giải trình, bổ sung thông tỉn, tài liệu của
cơ quan quản lý thuế; cung cấp kịp thời, đầy đủ, chính xác, trung thực các thông
tin, tài liệu liên quan đến nội dung kiểm tra thuế; ký biên bản kiểm tra thuế trong
thời hạn quy định của pháp luật; chấp hành kết luận, quyết định xử lý kết quả
kiểm tra thuế.$md$,$md$Luật quản lý thuế 2025_Điều37$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
