insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều38_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Nhiệm vụ của cơ quan quản lý thuế, công chức quản lý thuế:
<!-- Page Break -->
## Page 44
44
pháp luật về thuế, tiền chậm nộp, tiền thu từ xử phạt vi phạm hành chính do cơ quan
quản lý thuế thực hiện theo quy định của pháp luật về xử lý vi phạm hành chính;
phí theo quy định của Luật Phí và lệ phí; tiền sử dụng đất; tiền thuê đất; tiền cấp
quyền khai thác khoáng sản; tiền cấp quyền khai thác tài nguyên nước; tiền sử
dụng khu vực biển; thu từ chuyển đổi sở hữu doanh nghiệp, đơn Vị sự nghiệp công
lập; thu từ chuyển nhượng vốn, chuyển nhượng quyền mua cỗ phần, quyền góp
vốn nhà nước tại doanh nghiệp; lợi nhuận sau thuế còn lại sau khi trích lập các
quỹ theo quy định của doanh nghiệp do Nhà nước nắm giữ 100% vốn điều lệ, cổ
tức và lợi nhuận được chia cho phần vốn nhà nước tại doanh nghiệp theo quy
định; các khoản thu khác thuộc ngân sách nhà nước theo quy định của pháp luật.
Đối với các khoản phí, lệ phí không do cơ quan quản lý thuế trực tiếp thu thì
cơ quan, tổ chức được giao thu phí, lệ phí theo quy định của Luật Phí và lệ phí thực
hiện các nội dung quản lý thu theo quy định tại khoản 7 Điều 39 của Luật này.
Đối với các khoản thu thuộc lĩnh vực quản lý nhà nước của cơ quan, tổ chức
khác nhưng giao cho cơ quan quản lý thuế tổ chức thu thì cơ quan, tổ chức quản
lý khoản thu có trách nhiệm chuyền thông tin về việc xác định nghĩa vụ tài chính,
nghĩa vụ phải nộp ngân sách nhà nước cho cơ quan quản lý thuế tổ chức thu và
chịu trách nhiệm về tính chính xác, đầy đủ, kịp thời của thông tin nghĩa vụ tài
chính, nghĩa vụ phải nộp ngân sách nhà nước theo quy định của pháp luật. Trường
hợp có sự thay đổi các thông tin liên quan đến xác định nghĩa vụ tài chính, nghĩa
vụ nộp ngân sách nhà nước đã chuyển cho cơ quan quản lý thuế thì cơ quan, tổ
chức quản lý khoản thu có trách nhiệm thông báo cho cơ quan quản lý thuế để
điều chỉnh, thông báo số tiền thuế và khoản thu khác, tiền chậm nộp, tiền phạt
phải nộp của người nộp thuế;
người nộp thuế; công khai quy trình, thủ tục hành chính thuế, các chương trình
khuyến khích tuân thủ tự nguyện, chế độ ưu tiên tại trụ sở, trung tâm phục vụ hành
chính công cắp tỉnh, cắp xã, trên Hệ thống thông tin quản lý thuế và các phương
tiện thông tin đại chúng; ứng dụng công nghệ số để nâng cao hiệu quả hỗ trợ người
nộp thuế kê khai, báo cáo, thực hiện nghĩa vụ thuế và nâng cao tuân thủ pháp luật
về thuế;
thuế theo quy định;
tin theo đúng trình tự, thủ tục theo quy định của pháp luật. Xác nhận hoàn thành
<!-- Page Break -->
## Page 45
45
giao dịch trong trường hợp người nộp thuế hoàn thành giao dịch theo phương thức
điện tử;
thuế (bao gồm số tiền thuế, khoản thu khác nộp thừa), thông báo só tiền thuế nợ
qua tài khoản giao dịch điện tử của người nộp thuế;
trách nhiệm bồi thường của Nhà nước trong trường hợp gây thiệt hại trái pháp luật;
quyên nhăm xác định nghĩa vụ thuê phải nộp;
thông tin và chuyển đổi số trong quản lý thuế; bảo đảm an toàn dữ liệu, kết nối
liên thông với hệ thống của các cơ quan nhà nước có liên quan;
tiền phạt do cơ quan quản lý thuế phải thu, đã thu, miễn, giảm, xóa nợ, hoàn trả
theo quy định của pháp luật về kế toán và pháp luật về ngân sách nhà nước;
I) Tổ chức thực hiện công tác thống kê thuế theo quy định của pháp luật;
mại điện tử, tài sản số và loại hình, giao dịch kinh tế mới phát sinh;
sơ thuế trong phạm vi hồ sơ, tài liệu, thông tin của người nộp thuế cung cấp, cơ
sở dữ liệu quản lý thuế, thông tin của cơ quan nhà nước có thấm quyền cung cấp
có liên quan đến người nộp thuế, kết quả áp dụng quản lý rủi ro trong quản lý
thuế, bảo đảm theo đúng chức trách, nhiệm vụ, tuân thủ quy định của pháp luật
về thuế, quản lý thuế và quy định khác của pháp luật có liên quan, không chịu
trách nhiệm về những nội dung trong các văn bản, giấy tờ, tài liệu có trong hồ sơ
