insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều39_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Hội đồng nhân dân các cấp, trong phạm vi nhiệm vụ, quyền hạn của
mình, quyết định nhiệm vụ thu ngân sách hằng năm và giám sát việc thực hiện
pháp luật về thuế tại địa phương.
BỘ Ủy ban nhân dân các cấp, trong phạm vi nhiệm vụ, quyền hạn của mình,
có nhiệm vụ sau đây:
quản lý thuế lập dự toán và tổ chức thực hiện nhiệm vụ thu thuế, các khoản thu
khác thuộc ngân sách nhà nước trên địa bàn; thực hiện kê biên tài sản, bán đấu giá
tài sản đối với người nộp thuế bị cưỡng chế thi hành quyết định hành chính về
quản lý thuế bằng biện pháp kê biên tài sản, bán đấu giá tài sản kê biên;
thâm quyên trong việc quản lý, thực hiện pháp luật về thuế;
việc thực hiện pháp luật về thuế theo thẩm quyền;
ngân sách nhà nước không do cơ quan quản lý thuế quản lý thu thuộc thâm quyền
của Ủy ban nhân dân các cấp.$md$,$md$Luật quản lý thuế 2025_Điều39$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
