insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều39_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Cơ quan nhà nước, tổ chức được giao quản lý thu đối với các khoản thu
khác thuộc ngân sách nhà nước thực hiện tổ chức thu vào ngân sách nhà nước
theo quy định của pháp luật chuyên ngành và được áp dụng quy định về tính tiền
chậm nộp, xử lý số tiền nộp thừa theo quy định của Luật này, kiến nghị cơ quan
nhà nước có thâm quyền thực hiện các biện pháp cưỡng chế quy định tại các điểm
e, d,h khoản 1 Điều 49 của Luật này, bao gồm:
được giao quản lý thu thực hiện theo quy định của pháp luật về xử lý vi phạm
hành chính;
dụng tài sản công từ việc quản lý, sử dụng, khai thác tài sản công vào mục đích
kinh doanh, cho thuê, liên doanh, liên kết, xử lý tài sản công sau khi thực hiện
nghĩa vụ thuế, phí, lệ phí;$md$,$md$Luật quản lý thuế 2025_Điều39$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
