insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều39_K10$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 10$md$,$md$Nhiệm vụ, quyền hạn của cơ quan thanh tra:
của pháp luật về thanh tra, pháp luật về thuế và quy định khác của pháp luật có
liên quan;
quy định của Luật Thanh tra có nội dung kết luận về nghĩa vụ thuề và khoản thu
khác phải nộp ngân sách nhà nước của người nộp thuế thì cơ quan thanh tra có
trách nhiệm xác định hành vi vi phạm trong lĩnh vực quản lý thuế của người nộp
thuế và gửi biên bản, kết luận hoặc quyết định xử lý sau thanh tra cho người nộp
thuế và người nộp thuế có trách nhiệm thực hiện kết luận hoặc quyết định xử lý
sau thanh tra của cơ quan thanh tra. Cơ quan quản lý thuế căn cứ hành vi vi phạm
hành chính của người nộp thuế tại văn bản do cơ quan thanh tra lập và gửi cho cơ
<!-- Page Break -->
## Page 50
S0
quan quản lý thuế đề tiến hành xử phạt vỉ phạm hành chính về quản lý thuế theo
quy định của Luật Xử lý vi phạm hành chính và Luật này. Trường hợp người nộp
thuế không đồng ý với kết luận, quyết định xử lý sau thanh tra và việc xác định
hành vi vi phạm trong lĩnh vực quản lý thuế của cơ quan thanh tra thì người nộp
thuế có quyền khiếu nại kết luận, quyết định của cơ quan thanh tra;
nộp thuế mà thực hiện thanh tra tại cơ quan quản lý thuế có nội dung kiến nghị
nêu trong kết luận thanh tra hoặc quyết định xử lý sau thanh tra liên quan đến
nghĩa vụ thuế và khoản thu khác phải nộp ngân sách nhà nước của người nộp thuế
thì cơ quan thanh tra có trách nhiệm xác định hành vi vi phạm trong lĩnh vực quản
lý thuế của người nộp thuế và gửi bản trích sao có kết luận hoặc quyết định xử lý
sau thanh tra liên quan đến nghĩa vụ thuế và khoản thu khác phải nộp cho người
nộp thuế đề thực hiện. Cơ quan quản lý thuế có trách nhiệm tổ chức thực hiện kết
luận hoặc quyết định xử lý sau thanh tra của cơ quan thanh tra. Trường hợp người
nộp thuế không đồng ý với nghĩa vụ thuế và khoản thu khác phải nộp thì người
nộp thuế có văn bản đề nghị cơ quan quản lý thuế, cơ quan thanh tra xem xét lại
nghĩa vụ thuế, khoản thu khác phải nộp. Căn cứ đề nghị của người nộp thuế, cơ
quan thanh tra chủ trì, phối hợp với cơ quan quản lý thuế thực hiện việc xác định
chính xác nghĩa vụ thuế, khoản thu khác của người nộp thuế và chịu trách
