insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều40_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Tổ chức tín dụng, chỉ nhánh ngân hàng nước ngoài, tô chức cung ứng
dịch vụ thanh toán, tổ chức cung ứng dịch vụ trung gian thanh toán có nhiệm vụ,
quyền hạn sau:
hiện nộp thuế, khoản thu khác điện tử, hoàn thuế điện tử cho người nộp thuế; xử
lý, đối soát dữ liệu về nộp thuế, khoản thu khác điện tử, hoàn thuế điện tử; truyền,
nhận chứng từ nộp thuế điện tử, chuyển tiền vào ngân sách và gửi thông tin cho
cơ quan quản lý thuế đầy đủ, chính xác, kịp thời theo quy định của pháp luật;
không được hủy lệnh chuyển tiền sau khi thông tin nộp thuế đã được chuyền đến
cơ quan quản lý thuế; hỗ trợ người nộp thuế trong quá trình thực hiện nộp thuế
điện tử; bảo mật thông tin của người nộp thuế, người khai hải quan theo quy định
của pháp luật;
<!-- Page Break -->
## Page 52
52
thuế của người nộp thuế khi mở, đóng tài khoản thanh toán tại tổ chức cung ứng
dịch vụ thanh toán được mở tài khoản thanh toán;
thông tin khác của người nộp thuế để phục vụ quản lý thuế; cung cấp các thông
tín, các giao dịch bất thường, cung cấp đầy đủ, kịp thời, chính xác thông tin theo
yêu cầu của cơ quan thuế đề thực hiện các điều ước quốc tế hoặc thỏa thuận quốc
tế về thuế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên hoặc là
bên ký kết theo yêu cầu của cơ quan quản lý thuế;
khoản, phong tỏa tài khoản của người nộp thuế bị cưỡng chế thi hành quyết định
hành chính về quản lý thuế bằng phương thức điện tử; trích tiền để nộp thuế,
khoản thu khác từ tài khoản của người nộp thuế, phong tỏa tài khoản của người
nộp thuế bị cưỡng chế thi hành quyết định hành chính về quản lý thuế theo đề
nghị của cơ quan quản lý thuế;
nộp, tiền phạt và các khoản thu khác thuộc ngân sách nhà nước theo quy định của
Luật này nhưng người nộp thuế không nộp đúng thời hạn thì tổ chức bảo lãnh phải
chịu trách nhiệm nộp đủ tiền thuế, tiền chậm nộp, tiền phạt và các khoản thu khác
thuộc ngân sách nhà nước thay cho người nộp thuế trong phạm vi bảo lãnh đã thỏa
thuận tại hợp đồng, thỏa thuận, cam kết và thời hạn bảo lãnh;
nước) cung cấp thông tỉn về hàng hóa nhập khẩu được thế chấp làm tài sản bảo
đảm các khoản vay theo yêu cầu của cơ quan hải quan;
bán tài sản bảo đảm để xử lý nợ theo quy định của pháp luật về xử lý tài sản bảo
đảm và pháp luật về các tổ chức tín dụng thì bên nhận bảo đảm hoặc người mua
theo thỏa thuận theo pháp luật về dân sự có trách nhiệm kê khai, nộp đầy đủ các
nghĩa vụ thuế liên quan đến giao dịch xử lý tài sản bảo đảm thay cho bên bảo đảm.
Trường hợp bán tài sản bảo đảm là hàng hoá nhập khẩu thuộc đối tượng
miễn thué, không chịu thuế thì bên bán tài sản bảo đảm hoặc người mua theo thỏa
thuận theo pháp luật về dân sự có trách nhiệm kê khai, nộp đầy đủ các nghĩa vụ
thuế liên quan đến tài sản bảo đảm thay cho bên bảo đảm;
vào ngân sách nhà nước do lỗi của tổ chức cung ứng dịch vụ thanh toán, tổ chức
cung ứng dịch vụ trung gian thanh toán dẫn đến người nộp thuế bị tính tiền chậm
nộp thì tổ chức cung ứng dịch vụ thanh toán, tổ chức cung ứng dịch vụ trung gian
<!-- Page Break -->
## Page 53
3
thanh toán có trách nhiệm thanh toán tiền chậm nộp cho người nộp thuế theo quy
định của Luật này;
với cơ quan quản lý thuế trong công tác thu thuế.$md$,$md$Luật quản lý thuế 2025_Điều40$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
