insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều40_K5$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 5$md$,$md$Đại lý thuế, hộ kinh doanh, cá nhân kinh doanh dịch vụ làm thủ tục về thuế:
của pháp luật, có ít nhất 02 người có đủ tiêu chuẩn kinh doanh dịch vụ tư vấn thuế,
làm việc toàn thời gian tại doanh nghiệp, thực hiện các dịch vụ làm thủ tục về thuế
theo thỏa thuận với người nộp thuế;
nhân có đủ tiêu chuẩn kinh doanh dịch vụ tư vấn thuế và hoạt động theo quy định
của pháp luật, thực hiện các dịch vụ làm thủ tục về thuế theo thỏa thuận với người
nộp thuế;
thủ tục về thuế cung cấp cho người nộp thuế theo hợp đồng bao gồm: thủ tục đăng
ký thuế, khai thuế, nộp thuế, quyết toán thuế, lập hồ sơ đề nghị miễn thuế, giảm
thuế, hoàn thuế và các thủ tục về thuế khác thay người nộp thuế; dịch vụ tư vấn
thuế; dịch vụ kế toán theo quy định của pháp luật về kế toán;
thuế có quyền, nghĩa vụ sau: tuân thủ quy định của Luật này, pháp luật về thuế và
quy định khác của pháp luật có liên quan trong hoạt động hành nghề dịch vụ làm
