insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều41_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Người nộp thué, tô chức, cá nhân có quyền khiếu nại với cơ quan có thâm
quyền đối với quyết định hành chính, hành vi hành chính của cơ quan quản lý
thuế, người có thâm quyền của cơ quan quản lý thuế khi có căn cứ cho rằng quyết
định hoặc hành vi đó là trái pháp luật, xâm phạm trực tiếp đến quyền, lợi ích hợp
pháp của mình. Người khiếu nại được biết trình tự, thủ tục giải quyết khiếu nại
trên Hệ thống thông tỉn quản lý thuế theo quy định của pháp luật.$md$,$md$Luật quản lý thuế 2025_Điều41$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
