insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều42$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 42. Trách nhiệm và quyền hạn của cơ quan quản lý thuế trong$md$,$md$Trách nhiệm và quyền hạn của cơ quan quản lý thuế trong
việc giải quyết khiếu nại về thuế
1;Cỡ quan quản lý thuế nhận được khiếu nại về việc thực hiện pháp luật về
thuế có quyền yêu cầu người khiếu nại cung cấp hồ sơ, tài liệu liên quan đến việc
