insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều42_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Cơ quan quản lý thuế phải hoàn trả số tiền thuế, khoản thu khác, tiền
