insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều42_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Đối với vụ việc khiếu nại phức tạp, thủ trưởng cơ quan quản lý thuế là
người giải quyết khiếu nại thực hiện tham vấn các cơ quan, tổ chức có liên quan,
bao gồm cả khiếu nại lần đầu. Khi thực hiện việc tham vấn, thủ trưởng cơ quan
quản lý thuế phải ban hành quyết định thành lập Hội đồng tham vấn. Hội đồng
tham vấn hoạt động theo nguyên tắc tập thẻ, biểu quyết theo đa số. Kết quả biểu
quyết là cơ sở để thủ trưởng cơ quan quản lý thuế tham khảo khi ra quyết định xử
lý khiếu nại. Thủ trưởng cơ quan quản lý thuế là người ra quyết định và chịu trách
nhiệm về quyết định xử lý khiếu nại.$md$,$md$Luật quản lý thuế 2025_Điều42$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
