insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều44_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Trường hợp không xử phạt vi phạm hành chính về quản lý thuế:
45 của Luật này nhưng đã khai bổ sung hồ sơ khai thuế và đã tự giác nộp đủ số
tiền thuế phải nộp trước thời điểm cơ quan thuế công bố quyết định kiểm tra thuế,
cơ quan có thẩm quyền khác công bố quyết định thanh tra, kiểm tra tại trụ sở
người nộp thuế hoặc trước thời điểm cơ quan thuế phát hiện không qua kiểm tra
thuế tại trụ sở của người nộp thuế hoặc trước khi cơ quan có thẩm quyền khác
phát hiện; cá nhân trực tiếp quyết toán thuế thu nhập cá nhân chậm nộp hồ sơ
quyết toán thuế thu nhập cá nhân mà có phát sinh số tiền thuế được hoàn và các
trường hợp không bị xử phạt vi phạm hành chính khác quy định tại Luật này, quy
định khác của pháp luật có liên quan và các trường hợp khác theo quy định của
Chính phủ;
Điều 45 của Luật này nhưng đã khai bổ sung trước thời điểm cơ quan hải quan
thông báo việc kiểm tra trực tiếp hồ sơ hải quan đối với hàng hóa đang làm thủ
tục hải quan; người nộp thuế khai bổ sung trong thời hạn 60 ngày kể từ ngày
thông quan và trước thời điểm quyết định thanh tra, kiểm tra đối với hàng hóa
đã thông quan, kiểm tra sau thông quan và các trường hợp khác theo quy định
của Chính phủ.$md$,$md$Luật quản lý thuế 2025_Điều44$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
