insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều44_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Đối với cùng một hành vi vi phạm hành chính về quản lý thuế thì mức
phạt tiền đối với tổ chức bằng 02 lần mức phạt tiền đối với cá nhân. Riêng đối với
hành vi khai sai dẫn đến thiếu số tiền thuế phải nộp hoặc tăng số tiền thuế được
miễn, giảm, hoàn, không thu và hành vi trốn thuế thì mức phạt tiền không phân
biệt giữa tổ chức và cá nhân.
