insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều44_K5$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 5$md$,$md$Trường hợp người nộp thuế bị ấn định thuế theo quy định tại Điều 24 và
Điều 25 của Luật này thì tùy theo tính chất, mức độ của hành vi vi phạm có thể bị
xử phạt vi phạm hành chính về quản lý thuế theo quy định của Luật này.$md$,$md$Luật quản lý thuế 2025_Điều44$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều44_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Trường hợp vi phạm pháp luật về quản lý thuế đến mức phải truy cứu
trách nhiệm hình sự thì thực hiện theo quy định của pháp luật về hình sự.$md$,$md$Luật quản lý thuế 2025_Điều44$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều44_K7$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 7$md$,$md$Đối với hành vi vi phạm thủ tục thuế thì thời hiệu xử phạt là 02 năm.
Đối với hành vi trốn thuế chưa đến mức truy cứu trách nhiệm hình sự, hành vi
khai sai dẫn đến thiếu số tiền thuế phải nộp hoặc tăng số tiền thuế được miễn,
giảm, hoàn, không thu thì thời hiệu xử phạt là 05 năm. Thời điểm để tính thời
hiệu xử phạt vi phạm hành chính thực hiện theo quy định của pháp luật về xử lý
vi phạm hành chính.
§. Quá thời hiệu xử phạt vi phạm hành chính về quản lý thuế thì người nộp
thuế không bị xử phạt nhưng vẫn phải nộp đủ số tiền thuế thiếu, số tiền thuế trốn,
số tiền thuế được miễn, giảm, hoàn, không thu không đúng, tiền chậm nộp vào
ngân sách nhà nước trong thời hạn 10 năm trở về trước kể từ ngày phát hiện hành
vi vi phạm. Trường hợp người nộp thuế không đăng ký thuế thì phải nộp đủ số
tiền thuế thiếu, số tiền thu trốn, tiền chậm nộp cho toàn bộ thời gian trở về trước
kể từ ngày phát hiện hành vi vi phạm.$md$,$md$Luật quản lý thuế 2025_Điều44$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
