insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều45_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Hành vi trốn thuế:
khai thuế sau 90 ngày kê từ ngày hết thời hạn nộp hồ sơ khai thuế hoặc ngày hết
thời hạn gia hạn nộp hồ sơ khai thuế theo quy định của Luật này dẫn đến thiếu số
tiền thuế phải nộp hoặc tăng số tiền thuế được miễn, giảm, hoàn;
việc xác định số tiền thuế phải nộp;
quy định của pháp luật hoặc ghi giá trị trên hóa đơn bán hàng thấp hơn giá trị
thanh toán thực tế của hàng hóa, dịch vụ đã bán để khai thuế;
hóa đơn, chứng từ để hạch toán hàng hóa, dịch vụ mua vào trong hoạt động phát
sinh nghĩa vụ thuế làm giảm số tiền thuế phải nộp hoặc làm tăng số tiền thuế được
miễn, số tiền thuế được giảm hoặc tăng số tiền thuế được khấu trừ, số tiền thuế
được hoàn, số tiền thuế không phải nộp;
giá trị giao dịch thực tế để xác định sai số tiền thuế phải nộp, số tiền thuế được
miễn, số tiền thuế được giảm, số tiền thuế được hoàn, số tiền thuế không phải nộp;
vi phạm không tự nguyện khắc phục hậu quả bằng cách nộp đủ số tiền thuế phải
nộp theo quy định;
<!-- Page Break -->
