insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều49_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Các biện pháp cưỡng chế thi hành quyết định hành chính về quản lý thuế
bao gồm:
hành chính về quản lý thuế tại tổ chức tín dụng, chỉ nhánh ngân hàng nước ngoài;
phong tỏa tài khoản;
hành chính về quản lý thuế đo cơ quan, tổ chức, cá nhân khác đang nắm giữ;
doanh nghiệp, giây chứng nhận đăng ký hợp tác xã, giấy chứng nhận đăng ký tổ
hợp tác, giấy chứng nhận đăng ký hộ kinh doanh, giấy phép thành lập và hoạt
động, giấy phép hành nghề, giấy chứng nhận đăng ký hoạt động chi nhánh, văn
phòng đại diện, giấy chứng nhận đăng ký địa điểm kinh doanh, đăng ký hoặc giấy
phép hoạt động kinh doanh nền tảng thương mại điện tử.
