insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều4_K1$md$,$md$68-ndcp.signed$md$,$md$Khoản 1$md$,$md$Cá nhân cư trú có hoạt động sản xuất, kinh doanh, bao gồm cả cá nhân
đăng ký thành lập hộ kinh doanh hoặc người được các thành viên hộ gia đình
ủy quyên làm người đại diện hộ kinh doanh (sau đây gọi là cá nhân kinh doanh)
có mức doanh thu năm từ 500 triệu đồng trở xuống không phải nộp thuế thu
nhập cá nhân.$md$,$md$68-ndcp.signed_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều4_K2$md$,$md$68-ndcp.signed$md$,$md$Khoản 2$md$,$md$Cá nhân kinh doanh có doanh thu năm trên mức doanh thu quy định tại
khoản 1 Điều này thực hiện nộp thuế theo quy định tại Điều 7 Luật Thuế thu
nhập cá nhân sô 109/2025/QHI15.$md$,$md$68-ndcp.signed_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều4_K3$md$,$md$68-ndcp.signed$md$,$md$Khoản 3$md$,$md$Đối với cá nhân kinh doanh nộp thuế thu nhập cá nhân theo quy định
tại khoản 3 Điều 7 Luật Thuế thu nhập cá nhân số 109/2025/QH15, trường hợp
cá nhân có nhiều ngành, nghề kinh doanh áp dụng các mức thuế suất thuế thu
nhập cá nhân khác nhau hoặc có nhiều địa điểm kinh doanh thì cá nhân được
áp dụng mức trừ 500 triệu đồng trước khi tính thuế thu nhập cá nhân đối với
một hoặc một số ngành, nghề kinh doanh hoặc địa điểm kinh doanh do cá nhân
lựa chọn theo phương án có lợi nhất, nhưng tổng mức trừ không vượt quá 500
triệu đồng trong một năm đối với doanh thu của toàn bộ hoạt động kinh doanh
quy định tại khoản này.
Trường hợp doanh thu từ ngành, nghề kinh doanh hoặc địa điểm kinh
doanh được lựa chọn chưa trừ đủ 500 triệu đồng, cá nhân được trừ tiếp mức
chưa trừ hết vào doanh thu của một hoặc một sô ngành, nghề kinh doanh hoặc
địa điểm kinh doanh khác cho đến khi tổng mức trừ đủ 500 triệu đồng. `$md$,$md$68-ndcp.signed_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều4_K4$md$,$md$68-ndcp.signed$md$,$md$Khoản 4$md$,$md$Đối với cá nhân cho thuê bắt động sản nộp thuế thu nhập cá nhân theo
quy định tại khoản 4 Điều 7 Luật Thuế thu nhập cá nhân số 109/2025/QH15:
<!-- Page Break -->
# Page 3
nhau, cá nhân được trừ 500 triệu đồng trước khi tính thuế thu nhập cá nhân đối
với một hoặc một số hợp đồng cho thuê bất động sản do cá nhân lựa chọn nhưng
tổng mức được trừ không quá 500 triệu đồng một năm đối với tất cả hợp đồng
cho thuê bắt động sản. Trường hợp hợp đồng cho thuê bất động sản được lựa
chọn chưa trừ đủ 500 triệu đồng, cá nhân được tiếp tục lựa chọn các hợp đông
cho thuê bất động sản khác để được trừ tiếp cho đến khi trừ đủ 500 triệu đồng;
nhau và có quy định bên đi thuê khai thay, nộp thay thuế, khi lựa chọn hợp
đồng cho thuê bất động sản để áp dụng mức được trừ khi tính thuế thu nhập cá
nhân, cá nhân cho thuê bắt động sản và bên đi thuê phải quy định rõ trong hợp
đồng cho thuê bất động sản nội dung khai thay, nộp thay thuế và số tiền được
trừ khi tính thuế thu nhập cá nhân. Trường hợp hợp đồng cho thuê bất t động sản
có quy định khai thay, nộp thay thuế nhưng chưa trừ đủ 500 triệu đồng thì cá
nhân được tiếp tục lựa chọn các hợp đồng cho thuê bất động sản khác để tiếp
tục được trừ cho đến khi trừ đủ 500 triệu đồng.$md$,$md$68-ndcp.signed_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
