insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều5_K1$md$,$md$68-ndcp.signed$md$,$md$Khoản 1$md$,$md$Doanh thu là toàn bộ tiền bán hàng, tiền gia công, tiền cung ứng dịch
vụ kể cả trợ giá, phụ thu, phụ trội mà hộ kinh doanh, cá nhân kinh doanh được
hưởng, không phân biệt đã thu được tiền hay chưa thu được tiền; bao gồm cả
các khoản thưởng được nhận, khoản được nhận từ hỗ trợ đạt doanh số, khuyến
mại, chiết khấu thanh toán, khoản hỗ trợ được nhận bằng tiền hoặc không bằng
tiền, các khoản bồi thường vi phạm hợp đồng, bồi thường khác liên quan đến
hoạt động kinh doanh, doanh thu khác mà cá nhân kinh doanh được nhận không
phân biệt đã thu được tiền hay chưa thu được tiền, không bao gồm chiết khấu
thương mại, giảm giá hàng bán và giá trị hàng bán bị trả lại.$md$,$md$68-ndcp.signed_Điều5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều5_K2$md$,$md$68-ndcp.signed$md$,$md$Khoản 2$md$,$md$Doanh thu đối với một số trường hợp được quy định cụ thể như sau:
bao gồm cả tiền công, chỉ phí về nhiên liệu, động lực, vật liệu phụ và chỉ phí
khác phục vụ cho việc gia công hàng hóa;
trả chậm là tiền bán hàng hóa, dịch vụ trả tiền một lần, không bao gồm tiền lãi
trả góp, tiền lãi trả chậm;
đại lý là tiền hoa hông được hưởng theo hợp đồng đại lý;
hợp đồng thuê. Trường hợp bên thuê trả tiền trước cho nhiều năm thì doanh thu
để tính thu nhập chịu thuế được phân bổ cho số năm trả tiền trước hoặc được
xác định theo doanh thu trả tiền một lần;
cho nhiều năm thì doanh thu để tính thu nhập chịu thuế được phân bổ cho số
năm trả tiền trước hoặc xác định theo doanh thu trả tiền một lần;
hàng hóa, hành lý phát sinh trong kỳ tính thuế;
mục công trình hoặc giá trị khối lượng công trình xây dựng, lắp đặt nghiệm thu,
bao gôm cả giá trị nguyên vật liệu, máy móc, thiết bị; trường hợp xây dựng, lắp
đặt không bao thầu nguyên vật liệu, máy móc, thiết bị là số tiền từ hoạt động
xây dựng, lắp đặt không bao gồm giá trị nguyên vật liệu, máy móc, thiết bị.$md$,$md$68-ndcp.signed_Điều5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
