insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$68-ndcp.signed_Điều15_K2$md$,$md$68-ndcp.signed$md$,$md$Khoản 2$md$,$md$Trách nhiệm của Ủy ban nhân dân cấp xã
kinh doanh, cá nhân kinh doanh đang hoạt động trên địa bàn; phát hiện và thông
báo kịp thời cho cơ quan thuế các trường hợp: bắt đầu kinh doanh, tạm ngừng,
chấm đứt hoạt động, thay đổi ngành nghề, địa điểm kinh doanh trên địa bàn,
kinh doanh không đăng ký, kinh doanh trái phép, ngoài địa điểm được cấp phép;
chính sách pháp. luật về thuế đến người dân, hộ kinh doanh và cá nhân kinh
doanh. Hỗ trợ công tác tuyên truyền lưu động, niêm yết thông tin, hướng dẫn
người nộp thuế thực hiện kê khai, nộp thuế đúng quy định. Phản ánh các khó
khăn, vướng mắc của người dân liên quan đến chính sách thuế đến cơ quan thuế
để cùng phối hợp giải quyết;
<!-- Page Break -->
# Page 16
16
phối hợp và hỗ trợ cơ quan thuế theo thẩm quyền trong việc phát hiện, xác minh
và xử lý các hành vi vi phạm pháp luật thuế của hộ kinh doanh, cá nhân kinh
doanh khi có yêu cầu của cơ quan thuế; bao gồm việc xác minh thông tin người
nộp thuế, địa chỉ kinh doanh, quy mô hoạt động kinh doanh, số lượng hộ kinh
doanh, cá nhân kinh doanh, doanh thu, phối hợp lập biên bản vi phạm và cung
cấp ' hỗ sơ, tài liệu liên quan trên địa bàn theo quy định của pháp luật quản lý
thuế và pháp luật có liên quan;
liên quan trong việc kiểm tra, phát hiện, ngăn chặn và xử lý hành vi không đăng
ký kinh doanh, kinh doanh không khai thuế, trốn thuế;
doanh hoạt động kinh doanh tại các địa điểm kinh doanh trái phép, hoạt động
tại địa điểm kinh doanh không đủ điều kiện theo quy định của pháp luật;
quy định về tình hình hộ kinh doanh, cá nhân kinh doanh trên địa bàn; đề xuất
biện pháp tăng cường quản lý, xử lý vướng mắc phát sinh;
tỉnh và theo quy định của pháp luật để hỗ trợ công tác quản lý thuế đối với hộ
kinh doanh, cá nhân kinh doanh.$md$,$md$68-ndcp.signed_Điều15$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
