insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$141-ndcp.signed_Điều4_K3$md$,$md$141-ndcp.signed$md$,$md$Khoản 3$md$,$md$Trường hợp kỳ tính thuế năm 2025 có thời điểm kết thúc sau ngày 01
tháng 01 năm 2026 mà doanh nghiệp đáp ứng điều kiện quy định tại Điều 2
Nghị định này thì được miễn thuê thu nhập doanh nghiệp cho thời gian tính từ
ngày 01 tháng 01 năm 2026 đến hết kỳ tính thuế năm 2025. Số thuế thu nhập
doanh nghiệp được miễn thuế của kỳ tính thuế năm 2025 quy định tại khoản
này bằng tổng số thuế thu nhập doanh nghiệp phải nộp của năm 2025 chia cho
12 tháng (hoặc số tháng thực tế hoạt động của kỳ tính thuế năm 2025 đối với
trường hợp doanh nghiệp thành lập mới trong năm 2025) và nhân với số tháng
của kỳ tính thuế năm 2025 thuộc năm dương lịch 2026. Từ kỳ tính thuế năm
2026 thực hiện theo quy định tại Điều 2 Nghị định này.
